## Code Example

```javascript
// RN usage sketch
import { NativeModules, NativeEventEmitter } from 'react-native';
const { AudioRecorder } = NativeModules;
const emitter = new NativeEventEmitter(AudioRecorder);
const chunks = [];
emitter.addListener('onChunk', (e) => chunks.push(e.sample));
AudioRecorder.startRecording({ rate: 44100, bits: 16 });
// later
AudioRecorder.stopRecording();
const wavPath = AudioRecorder.getWavPath();
```

